const CACHE="mono-mock-v82";const ASSETS=["./card-motion.js?v=82","./card-photo.js?v=82","./card-photo.css?v=82","./assets/fonts/card-tech-mono.ttf","./secret-visibility.js?v=82","./launch.js?v=82","./apple-touch-icon.png?v=82","./icon-192.png?v=82","./auth-gate.js?v=82","./auth.css?v=82","./cabinets.js?v=82","./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=82","./bank-detail.js?v=82","./bank-detail.css?v=82","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=82","./mobile-stability.js?v=82","./mobile-stability.css?v=82","./pull-refresh.js?v=82","./hosted-storage.js?v=82","./card-stable.js?v=82","./card-stable.css?v=82","./profile-pwa.js?v=82","./profile-pwa.css?v=82","./history-glass.js?v=82","./history-glass.css?v=82","./faithful.css?v=82","./faithful-motion.js?v=82","./faithful-entry.js?v=82","./receipt-links.js?v=82","./native-reference.js?v=82","./native-reference.css?v=82","./reference-fidelity.js?v=82","./reference-fidelity.css?v=82","./continuity.js?v=82","./continuity.css?v=82","./motion.js?v=82","./motion.css?v=82","./recording.js?v=82","./recording.css?v=82","./interactions.js?v=82","./interactions.css?v=82","./surfaces.js?v=82","./surfaces.css?v=82","./refinement.css?v=82","./refinement.js?v=82","./reference.css?v=82","./experience.js?v=82","./style.css?v=82","./app.js?v=82","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=82","./pwa-runtime.css?v=82","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
